/**
 * Smart money structure on closed bars, oldest first: swing pivots, break of structure (BOS and CHoCH), order blocks,
 * fair value gaps and liquidity pools. Line by line port of python/jev_analytics/smc.py (spec section 3.4, SMC-1 to
 * SMC-6); the golden vectors in vectors/smc-vectors.v1.json are generated by the Python reference.
 *
 * Everything here describes where price has been and which zones are still untouched. Nothing returns an action,
 * a vote or a signal. What is known at bar k never changes when later bars arrive (no repainting).
 */

import { atr } from "./indicators";

export const SMC_FVG_MIN_ATR = 0.1;
export const SMC_POOL_TOLERANCE_ATR = 0.1;
export const SMC_ATR_PERIOD = 14;

export type SmcDir = "up" | "down";

export interface SmcSwing {
  readonly index: number;
  readonly price: number;
  readonly kind: "high" | "low";
  readonly confirmedAt: number;
}

export interface SmcEvent {
  readonly index: number;
  readonly type: "BOS" | "CHoCH";
  readonly dir: SmcDir;
  readonly level: number;
  readonly swingIndex: number;
}

/** `dir` up is a demand zone (after a break up), down is a supply zone. */
export interface SmcBlock {
  readonly index: number;
  readonly dir: SmcDir;
  readonly low: number;
  readonly high: number;
  readonly formedAt: number;
  mitigatedAt: number | null;
}

export interface SmcGap {
  readonly index: number;
  readonly dir: SmcDir;
  readonly low: number;
  readonly high: number;
  readonly fill: number;
  readonly filledAt: number | null;
}

export interface SmcPool {
  readonly kind: "eqh" | "eql";
  readonly price: number;
  readonly indices: readonly number[];
  readonly sweptAt: number | null;
  readonly takenAt: number | null;
}

export interface SmcRange {
  readonly low: number;
  readonly high: number;
  readonly lowIndex: number;
  readonly highIndex: number;
}

export type SmcRangeState = "inside" | "above" | "below";

export interface SmcResult {
  readonly n: number;
  readonly bars: number;
  readonly trend: SmcDir | null;
  readonly swings: readonly SmcSwing[];
  readonly events: readonly SmcEvent[];
  readonly orderBlocks: readonly SmcBlock[];
  readonly fvgs: readonly SmcGap[];
  readonly pools: readonly SmcPool[];
  readonly range: SmcRange | null;
  readonly position: number | null;
  readonly rangeState: SmcRangeState | null;
}

interface Pivot {
  readonly index: number;
  readonly price: number;
  broken: boolean;
}

const clamp01 = (value: number): number => Math.min(1, Math.max(0, value));

function swingMaps(h: readonly number[], l: readonly number[], n: number): { highs: Map<number, number>; lows: Map<number, number> } {
  const highs = new Map<number, number>();
  const lows = new Map<number, number>();
  for (let i = n; i < h.length - n; i += 1) {
    let isHigh = true;
    let isLow = true;
    for (let j = i - n; j < i; j += 1) {
      if (!(h[i]! > h[j]!)) isHigh = false;
      if (!(l[i]! < l[j]!)) isLow = false;
    }
    for (let j = i + 1; j <= i + n; j += 1) {
      if (!(h[i]! >= h[j]!)) isHigh = false;
      if (!(l[i]! <= l[j]!)) isLow = false;
    }
    if (isHigh) highs.set(i, h[i]!);
    if (isLow) lows.set(i, l[i]!);
  }
  return { highs, lows };
}

function readStructure(o: readonly number[], h: readonly number[], l: readonly number[], c: readonly number[], n: number, highs: Map<number, number>, lows: Map<number, number>) {
  const size = c.length;
  const swings: SmcSwing[] = [];
  const events: SmcEvent[] = [];
  const blocks: SmcBlock[] = [];
  let top: Pivot | null = null;
  let bottom: Pivot | null = null;
  let direction = 0;
  for (let k = 0; k < size; k += 1) {
    const i = k - n;
    const pivotHigh = highs.get(i);
    const pivotLow = lows.get(i);
    if (pivotHigh !== undefined) {
      top = { index: i, price: pivotHigh, broken: false };
      swings.push({ index: i, price: pivotHigh, kind: "high", confirmedAt: k });
    }
    if (pivotLow !== undefined) {
      bottom = { index: i, price: pivotLow, broken: false };
      swings.push({ index: i, price: pivotLow, kind: "low", confirmedAt: k });
    }
    if (top !== null && !top.broken && c[k]! > top.price) {
      events.push({ index: k, type: direction < 0 ? "CHoCH" : "BOS", dir: "up", level: top.price, swingIndex: top.index });
      top.broken = true;
      direction = 1;
      if (bottom !== null) {
        let pick = -1;
        for (let j = bottom.index; j < k; j += 1) {
          if (c[j]! < o[j]! && (pick < 0 || l[j]! <= l[pick]!)) pick = j;
        }
        if (pick >= 0 && !blocks.some((b) => b.index === pick && b.dir === "up")) {
          blocks.push({ index: pick, dir: "up", low: l[pick]!, high: h[pick]!, formedAt: k, mitigatedAt: null });
        }
      }
    } else if (bottom !== null && !bottom.broken && c[k]! < bottom.price) {
      events.push({ index: k, type: direction > 0 ? "CHoCH" : "BOS", dir: "down", level: bottom.price, swingIndex: bottom.index });
      bottom.broken = true;
      direction = -1;
      if (top !== null) {
        let pick = -1;
        for (let j = top.index; j < k; j += 1) {
          if (c[j]! > o[j]! && (pick < 0 || h[j]! >= h[pick]!)) pick = j;
        }
        if (pick >= 0 && !blocks.some((b) => b.index === pick && b.dir === "down")) {
          blocks.push({ index: pick, dir: "down", low: l[pick]!, high: h[pick]!, formedAt: k, mitigatedAt: null });
        }
      }
    }
  }
  for (const block of blocks) {
    for (let m = block.formedAt + 1; m < size; m += 1) {
      if ((block.dir === "up" && c[m]! < block.low) || (block.dir === "down" && c[m]! > block.high)) {
        block.mitigatedAt = m;
        break;
      }
    }
  }
  return { swings, events, blocks, direction, top, bottom };
}

function readGaps(h: readonly number[], l: readonly number[], atrSeries: readonly (number | null)[]): SmcGap[] {
  const size = h.length;
  const out: SmcGap[] = [];
  for (let i = 2; i < size; i += 1) {
    const a = atrSeries[i];
    if (a === null || a === undefined) continue;
    let lo: number;
    let hi: number;
    let up: boolean;
    if (l[i]! > h[i - 2]! && l[i]! - h[i - 2]! >= SMC_FVG_MIN_ATR * a) {
      lo = h[i - 2]!;
      hi = l[i]!;
      up = true;
    } else if (h[i]! < l[i - 2]! && l[i - 2]! - h[i]! >= SMC_FVG_MIN_ATR * a) {
      lo = h[i]!;
      hi = l[i - 2]!;
      up = false;
    } else {
      continue;
    }
    const span = hi - lo;
    let fill = 0;
    let filledAt: number | null = null;
    for (let m = i + 1; m < size; m += 1) {
      const reach = up ? hi - l[m]! : h[m]! - lo;
      fill = Math.max(fill, clamp01(reach / span));
      if (filledAt === null && ((up && l[m]! <= lo) || (!up && h[m]! >= hi))) filledAt = m;
    }
    out.push({ index: i, dir: up ? "up" : "down", low: lo, high: hi, fill, filledAt });
  }
  return out;
}

function readPools(h: readonly number[], l: readonly number[], c: readonly number[], highs: Map<number, number>, lows: Map<number, number>, atrLast: number | null): SmcPool[] {
  if (atrLast === null) return [];
  const tolerance = SMC_POOL_TOLERANCE_ATR * atrLast;
  const size = c.length;
  const out: SmcPool[] = [];
  for (const [kind, pivots] of [["eqh", highs], ["eql", lows]] as const) {
    const ordered = [...pivots.entries()].sort((a, b) => a[1] - b[1] || a[0] - b[0]);
    const groups: [number, number][][] = [];
    for (const entry of ordered) {
      const last = groups[groups.length - 1];
      if (last !== undefined && entry[1] - last[0]![1] <= tolerance) last.push(entry);
      else groups.push([entry]);
    }
    for (const group of groups) {
      if (group.length < 2) continue;
      const indices = group.map((e) => e[0]).sort((a, b) => a - b);
      const prices = group.map((e) => e[1]);
      const level = kind === "eqh" ? Math.max(...prices) : Math.min(...prices);
      let sweptAt: number | null = null;
      let takenAt: number | null = null;
      for (let m = indices[0]! + 1; m < size; m += 1) {
        if (kind === "eqh" && h[m]! > level) {
          if (c[m]! < level) sweptAt = m;
          else takenAt = m;
          break;
        }
        if (kind === "eql" && l[m]! < level) {
          if (c[m]! > level) sweptAt = m;
          else takenAt = m;
          break;
        }
      }
      out.push({ kind, price: level, indices, sweptAt, takenAt });
    }
  }
  return out;
}

/**
 * Smart money reading of closed bars. `price` is the current price for the premium and discount position and
 * defaults to the last close; the forming bar must not be part of the series.
 */
export function analyzeSmc(o: readonly number[], h: readonly number[], l: readonly number[], c: readonly number[], n = 3, price?: number): SmcResult {
  const size = c.length;
  if (o.length !== size || h.length !== size || l.length !== size) throw new RangeError("series must have the same length");
  if (!Number.isInteger(n) || n < 1) throw new RangeError("n must be positive");
  const atrSeries = atr(h, l, c, SMC_ATR_PERIOD);
  const { highs, lows } = swingMaps(h, l, n);
  const built = readStructure(o, h, l, c, n, highs, lows);
  const { top, bottom } = built;
  let range: SmcRange | null = null;
  let position: number | null = null;
  let state: SmcRangeState | null = null;
  const now = price !== undefined ? price : size > 0 ? c[size - 1]! : null;
  if (top !== null && bottom !== null && top.price > bottom.price && now !== null) {
    range = { low: bottom.price, high: top.price, lowIndex: bottom.index, highIndex: top.index };
    const raw = (now - bottom.price) / (top.price - bottom.price);
    state = raw > 1 ? "above" : raw < 0 ? "below" : "inside";
    position = clamp01(raw);
  }
  return {
    n,
    bars: size,
    trend: built.direction > 0 ? "up" : built.direction < 0 ? "down" : null,
    swings: built.swings,
    events: built.events,
    orderBlocks: built.blocks,
    fvgs: readGaps(h, l, atrSeries),
    pools: readPools(h, l, c, highs, lows, size > 0 ? atrSeries[size - 1] ?? null : null),
    range,
    position,
    rangeState: state,
  };
}

export interface SmcContext {
  readonly demandBlockBps: number | null;
  readonly supplyBlockBps: number | null;
  readonly gapsUp: number;
  readonly gapsDown: number;
  readonly gapNearestBps: number | null;
  readonly lastBreak: { readonly kind: "BOS" | "CHoCH"; readonly dir: SmcDir; readonly ageBars: number } | null;
  readonly rangePos: number | null;
  readonly rangeState: SmcRangeState | null;
  readonly poolAboveBps: number | null;
  readonly poolBelowBps: number | null;
  readonly lastSweep: { readonly kind: "highs" | "lows"; readonly ageBars: number } | null;
}

const edgeDistanceBps = (last: number, lo: number, hi: number): number => (last < lo ? lo - last : last > hi ? last - hi : 0) / last * 10_000;

/** The descriptive digest of the same reading, unrounded: the chart's context chips and the Jev's pack share these semantics. */
export function smcContext(result: SmcResult, last: number): SmcContext {
  const bars = result.bars;
  const liveBlocks = result.orderBlocks.filter((b) => b.mitigatedAt === null);
  const demand = liveBlocks.filter((b) => b.dir === "up" && b.low <= last);
  const supply = liveBlocks.filter((b) => b.dir === "down" && b.high >= last);
  const liveGaps = result.fvgs.filter((g) => g.fill < 1);
  const livePools = result.pools.filter((p) => p.sweptAt === null && p.takenAt === null);
  const above = livePools.filter((p) => p.kind === "eqh" && p.price >= last).map((p) => p.price);
  const below = livePools.filter((p) => p.kind === "eql" && p.price <= last).map((p) => p.price);
  const swept = result.pools.filter((p): p is SmcPool & { sweptAt: number } => p.sweptAt !== null);
  const lastBreak = result.events[result.events.length - 1];
  let lastSweep: SmcPool & { sweptAt: number } | undefined;
  for (const p of swept) {
    if (lastSweep === undefined || p.sweptAt > lastSweep.sweptAt || (p.sweptAt === lastSweep.sweptAt && p.kind === "eql")) lastSweep = p;
  }
  return {
    demandBlockBps: demand.length > 0 ? Math.max(0, (last - Math.max(...demand.map((b) => b.high))) / last * 10_000) : null,
    supplyBlockBps: supply.length > 0 ? Math.max(0, (Math.min(...supply.map((b) => b.low)) - last) / last * 10_000) : null,
    gapsUp: liveGaps.filter((g) => g.dir === "up").length,
    gapsDown: liveGaps.filter((g) => g.dir === "down").length,
    gapNearestBps: liveGaps.length > 0 ? Math.min(...liveGaps.map((g) => edgeDistanceBps(last, g.low, g.high))) : null,
    lastBreak: lastBreak === undefined ? null : { kind: lastBreak.type, dir: lastBreak.dir, ageBars: bars - 1 - lastBreak.index },
    rangePos: result.position,
    rangeState: result.rangeState,
    poolAboveBps: above.length > 0 ? (Math.min(...above) - last) / last * 10_000 : null,
    poolBelowBps: below.length > 0 ? (last - Math.max(...below)) / last * 10_000 : null,
    lastSweep: lastSweep === undefined ? null : { kind: lastSweep.kind === "eqh" ? "highs" : "lows", ageBars: bars - 1 - lastSweep.sweptAt },
  };
}
